const CountdownTimer = () => {
  const [timeLeft, setTimeLeft] = useState(3 * 3600 + 15 * 60 + 30);

  useEffect(() => {
    const interval = setInterval(() => {
      setTimeLeft((prev) => Math.max(prev - 1, 0));
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const hours = String(Math.floor(timeLeft / 3600)).padStart(2, "0");
  const minutes = String(Math.floor((timeLeft % 3600) / 60)).padStart(2, "0");
  const seconds = String(timeLeft % 60).padStart(2, "0");

  return (
    <div className="flex gap-1 items-center text-sm">
      <span className="text-black font-semibold">Flash sale</span>
      <span className="bg-red-500 text-white px-1 rounded">{hours}</span> :
      <span className="bg-red-500 text-white px-1 rounded">{minutes}</span> :
      <span className="bg-red-500 text-white px-1 rounded">{seconds}</span>
    </div>
  );
};

